package org.sleepwell.app;

import android.app.*;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.text.InputType;
import android.widget.*;
import java.util.*;

/** Silent station-library draft. Only explicit Play on the parent starts networking/audio. */
final class SleepRadioEditor {
    private final Activity activity;private final Runnable finished;private final SharedPreferences preferences;
    private SoundMix previous;private SleepRadio draft=SleepRadio.EMPTY;private long revision;private String error="",editing="",name="",url="";private boolean form;private EditText nameField,urlField;private Dialog dialog;
    SleepRadioEditor(Activity activity,Bundle saved,Runnable finished){this.activity=activity;this.finished=finished;preferences=SoundPreferences.factory.open(activity);try{previous=SoundPreferences.load(preferences).copy();draft=previous.radio;revision=SoundPreferences.revision(preferences);if(saved!=null){draft=SleepRadio.read(saved.getString("library",""));revision=saved.getLong("revision",revision);form=saved.getBoolean("form");editing=saved.getString("editing","");name=saved.getString("name","");url=saved.getString("url","");error=saved.getString("error","");if(name.length()>80||url.length()>2048||!editing.isEmpty()&&!BackupRuntime.nonce(editing))throw new IllegalArgumentException();}}catch(RuntimeException unreadable){previous=null;error="The saved mix or radio library is unreadable. Nothing was changed or connected.";}}
    Bundle state(){fields();Bundle out=new Bundle();out.putString("library",draft.encode());out.putLong("revision",revision);out.putBoolean("form",form);out.putString("editing",editing);out.putString("name",name);out.putString("url",url);out.putString("error",error);return out;}
    void render(){nameField=urlField=null;LinearLayout body=Design.page(activity,false,null,n->{});RecordUi.label(activity,body);RecordUi.header(body,form?"Radio station":"Internet radio",this::back);Design.space(body,14);
        if(previous==null){Design.text(body,error,14,500,Design.BROWN);Design.button(body,"Back to sounds",false,finished);return;}
        if(form){edit(body);return;}
        Design.text(body,"Your saved stations",23,600,Design.INK);Design.space(body,8);Design.text(body,"Direct public HTTPS audio only. Editing and saving never start a connection. Save pauses any current mix; return and tap Play to connect.",14,400,Design.MUTED);Design.space(body,14);
        if(draft.stations.isEmpty())Design.text(body,"No stations saved. Add a station name and its direct stream URL.",14,400,Design.MUTED);
        for(SleepRadio.Station station:draft.stations){LinearLayout row=PlanActivity.detail(body,"music",station.name,AlarmRadioUrl.host(station.url),station.id.equals(draft.selected)?"Selected":"Choose",()->options(station));row.setSelected(station.id.equals(draft.selected));Design.line(body);}
        Design.button(body,"Add radio station",false,()->{editing="";name=url="";form=true;error="";render();}).setEnabled(draft.stations.size()<SleepRadio.LIMIT);Design.space(body,10);
        Design.text(body,"Streaming uses your connection and data allowance. Stations may be offline or unsupported. No sign-in, Spotify/account links, web pages, token URLs or station-list files; there is no automatic fallback or reconnect.",12,400,Design.MUTED);Design.space(body,10);Design.text(body,"Saving pauses the current mix. Radio always uses manual Play, the same overall timer/fade and optional brown-noise bed. A stream ending or failing stops the whole mix.",12,400,Design.MUTED);
        if(previous.primary.equals(SleepRadio.NAME)&&draft.station()==null)Design.text(body,"The active station was removed. Save stations will select Rain silently; Play remains required.",13,500,Design.BROWN);
        message(body);LinearLayout footer=RecordUi.footer(body);SleepRadio.Station selected=draft.station();Design.button(footer,selected==null?"Choose a station to use":"Use "+selected.name,true,()->save(true)).setEnabled(selected!=null);Design.button(footer,"Save stations only",false,()->save(false));Design.button(footer,"Cancel",false,finished);
    }
    private void edit(LinearLayout body){Design.text(body,"Name",13,600,Design.INK);nameField=field(body,"Station name",name,80,false);Design.space(body,12);Design.text(body,"Direct HTTPS stream URL",13,600,Design.INK);urlField=field(body,"Station stream URL",url,2048,true);Design.space(body,10);Design.text(body,"Use the station’s public audio endpoint, not a listening page. No network check runs here. Playback support is checked only after you tap Play.",13,400,Design.MUTED);message(body);LinearLayout footer=RecordUi.footer(body);Design.button(footer,"Keep station in draft",true,()->{fields();try{SleepRadio.Station station=new SleepRadio.Station(editing.isEmpty()?UUID.randomUUID().toString():editing,name.strip(),url.strip());draft=draft.put(station);form=false;error="";render();}catch(IllegalArgumentException invalid){error=invalid.getMessage();render();}});Design.button(footer,"Cancel station edit",false,()->{form=false;error="";render();});}
    private EditText field(LinearLayout body,String label,String value,int limit,boolean uri){EditText edit=new EditText(activity);edit.setText(value);edit.setContentDescription(label);edit.setSingleLine(!uri);edit.setMaxLines(uri?3:1);edit.setTextSize(15*Appearance.scale(activity));edit.setTypeface(Design.font(activity,400));edit.setTextColor(Design.INK);edit.setHintTextColor(Design.MUTED);edit.setInputType(uri?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);edit.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(limit)});Design.pad(edit,12,12);edit.setBackground(Design.shape(activity,Design.SOFT,12));body.addView(edit,new LinearLayout.LayoutParams(-1,-2));return edit;}
    private void fields(){if(nameField!=null)name=nameField.getText().toString();if(urlField!=null)url=urlField.getText().toString();}
    private void options(SleepRadio.Station station){dialog=SleepPicker.choices(activity,station.name,new String[]{"Select station","Edit station","Remove station"},-1,which->{if(which==0){draft=draft.select(station.id);error="";render();}else if(which==1){editing=station.id;name=station.name;url=station.url;form=true;error="";render();}else{draft=draft.remove(station.id);error="";render();}});}
    private void message(LinearLayout body){if(!error.isEmpty()){Design.space(body,12);TextView view=Design.text(body,error,13,500,0xffa93919);view.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);}}
    private void save(boolean select){if(previous==null)return;try{SoundMix next=previous.copy();next.radio=draft;if(select){if(draft.station()==null)throw new IllegalArgumentException("Choose a station first.");next.primary=SleepRadio.NAME;next.withTracking=false;}else if(next.primary.equals(SleepRadio.NAME)&&draft.station()==null){next.primary="Rain";next.withTracking=false;}next.validate();if(SoundPreferences.revision(preferences)!=revision)throw new IllegalStateException("The mix changed. Cancel and reopen radio before saving.");SleepSoundService.pauseForSelection();if(!SoundPreferences.saveIfRevision(preferences,revision,next))throw new IllegalStateException("The mix changed. Reopen radio before saving.");SoundPreferences.error(activity,"");SleepSoundService.update(activity);finished.run();}catch(RuntimeException failed){error=failed.getMessage()==null?"Stations could not be saved. Nothing was connected.":failed.getMessage();render();}}
    void back(){if(form){form=false;error="";render();}else finished.run();}
    void destroy(){if(dialog!=null){dialog.dismiss();dialog=null;}}
}
